The canonical dual frame of $f(x)$ is $\tilde{f}(x) = S^{-1}f(x)$. It is also sometimes referred to as ``the dual frame.''  If $S$ is the frame operator of $f$, then $S^{-1}$ is the frame operator of the dual frame $\tilde{f}$. Consequently, $f$ is the dual frame of $\tilde{f}$, so that for all $\phi\in H$,
\begin{equation}
\phi = \int_X\brak{\phi, \tilde{f}(x)} f(x)\,d\mu(x)
= \int_X\brak{\phi, S^{-1}f(x)} f(x)\,d\mu(x).
\end{equation}
It is important to note, however, that there are dual frames for $f$ other than the canonical dual. Also, in what follows, we will often use a subscript of $H$ to denote inner products or norms with respect to the initial Hilbert space $H$.

\begin{proof}
Let $A\in\operatorname{GL}(H)$ and $B\in\operatorname{GL}^+(H)$. For any $\phi\in H$, we have
\[ \brak{\operatorname{ad}_A(B)\phi, \phi}
= \brak{ABA^*\phi, \phi}
= \brak{BA^*\phi, A^*\phi}\geq 0, \]
where the inequality holds since $A^*\phi\in H$ and $B$ is positive. Thus, $\operatorname{ad}_A(B)$ is positive, so that $GL^+(H)$ is closed under adjugation. Let $B,C\in\operatorname{GL}^+(H)$. Since $B,C$ are positive, then $B=SS^*$ and $C=TT^*$ for some $S,T\in\operatorname{GL}(H)$. There exists $A\in\operatorname{GL}(H)$ such that $T=AS$. We have
\[ \operatorname{ad}_A(B) = ABA^*
= ASS^*A^*
= (AS)(AS)^*
= TT^*
= C. \]
Thus, $B\sim C$. Ergo, $\operatorname{GL}^+(H)$ is an adjugacy class.
\end{proof}

\noindent Because frame operators are elements of $\operatorname{GL}^+(H)$, the above proposition will be useful in subsequent discussions of frame operators.

Next, we define the projection 
\begin{equation}
\rho:\operatorname{GL}(H)\mapsto \operatorname{GL}^+(H), \quad
\rho(A)=AA^*,
\end{equation}
which is important in the proof of the following lemma establishing an important relationship between $\operatorname{GL}^+(H)$ and $\operatorname{GL}(H)$.

\begin{proof}
We have the operator norm
\[ \|A\|_J = \sup_{f\in J,f\neq 0} \frac{\|Af\|_J}{\|f\|_J}
= \sup_{f\in J,f\neq 0}\sup_{x\in X} \frac{\|Af(x)\|_H}{\|f\|_J}. \]
Since $A\in\operatorname{GL}(H)$, then we have
\begin{align*}
\sup_{f\in J,f\neq 0}\sup_{x\in X} \frac{1}{\|A^{-1}\|_H}\frac{\|f(x)\|_H}{\|f\|_J} \leq &\|A\|_J \leq \sup_{f\in J,f\neq 0}\sup_{x\in X} \|A\|_H \frac{\|f(x)\|_H}{\|f\|_J} \\
\frac{1}{\|A^{-1}\|_H} \sup_{f\in J,f\neq 0}\sup_{x\in X}\frac{\|f(x)\|_H}{\|f\|_J} \leq &\|A\|_J \leq \|A\|_H\sup_{f\in J,f\neq 0}\sup_{x\in X}\frac{\|f(x)\|_H}{\|f\|_J} \\
\frac{1}{\|A^{-1}\|_H}\sup_{f\in J,f\neq 0} \frac{\|f\|_J}{\|f\|_J} \leq &\|A\|_J \leq \|A\|_H\sup_{f\in J,f\neq 0} \frac{\|f\|_J}{\|f\|_J} \\
\frac{1}{\|A^{-1}\|_H} \leq &\|A\|_J \leq \|A\|_H.
\end{align*}
Therefore, $A\in\operatorname{GL}(J)$.
\end{proof}

Define the ``frame operator map'' $S:F\mapsto \operatorname{GL}^+(H)$ such that $S(f)$ is the frame operator of $f$. The following lemma is of central importance.

\begin{proof}
The reverse implication is trivial. For the forward implication, suppose $Af=f$. Recall $Af$ is defined by $(Af)(x) = A[f(x)]$ for all $x\in X$. Thus, $Af=f$ implies $A[f(x)] = f(x)$ for all $x\in X$. Since $f$ is a frame on $H$, the set $\{f(x):x\in X\}$ spans $H$. Since $A$ is linear on $H$, we have $A\phi = \phi$ for all $\phi\in H$. 
\end{proof}

Because the action of $\operatorname{GL}(H)$ is regular on each orbit in $F/\operatorname{GL}(H)$, every orbit is a principal homogeneous space. Therefore, the linear transformation connecting two frames is unique.

Lemma \ref{LinearDeform} implies that the frame operator map $S:F\mapsto \operatorname{GL}^+(H)$ may be thought of as a projection map, as the following proposition states.

\begin{proof}
Let $f\in F$. By Lemma \ref{LinearDeform}, observe that
\[ S(T(f)) = S(S(f)^{-\frac{1}{2}}f)
= S(f)^{-\frac{1}{2}}S(f) S(f)^{-\frac{1}{2}}
= I. \]
Thus, $T(f)\in F_0$, and hence $T$ is well-defined. Note $T$ fixes $F_0$ pointwise: If $f\in F_0$, then $T(f)=I^{-\frac{1}{2}}f=f$. Thus, $T$ is surjective.
\end{proof}

Therefore, every frame can be linearly transformed into a Parseval frame. But we would like this transformation to be unique in some sense. In particular, we would like to index the orbits in 
$F/\operatorname{GL}(H)$ by a set of Parseval frames. We must therefore determine how the Parseval frames in a common orbit in $F/\operatorname{GL}(H)$ are related. We recall that $F_0\subset F$ is the space of Parseval frames and consider the action of $U(H)$ on $F_0$.

Finally, we define the continuous projection maps
\begin{align*}
\pi_1:\operatorname{GL}(H)\times F_0\mapsto \operatorname{GL}(H), \quad
&\pi_1(A, f) = A \\
\pi_2:\operatorname{GL}(H)\times F_0\mapsto F_0, \quad
&\pi_2(A, f) = f.
\end{align*}
